-- audit_probe (workspace, append-only, definer)
alter table audit_probe enable row level security;
alter table audit_probe force row level security;
drop policy if exists cc_tenant on audit_probe;
create policy cc_tenant on audit_probe using (workspace_id = nullif(current_setting('app.current_workspace_id', true), '')::uuid) with check (workspace_id = nullif(current_setting('app.current_workspace_id', true), '')::uuid);
drop policy if exists cc_definer on audit_probe;
create policy cc_definer on audit_probe to cc_migrator using (true) with check (true);
drop trigger if exists cc_append_only on audit_probe;
revoke update, delete, truncate on audit_probe from cc_app;
create trigger cc_append_only before update or delete on audit_probe for each row execute function cc_reject_change();
drop trigger if exists cc_audit_probe on audit_probe;

